from langchain_core.tools import tool

@tool
def word_count(text: str) -> int:
    """Count the words in a piece of text."""
    return len(text.split())

# the decorator built a tool from the signature + docstring
print(word_count.name)          # 'word_count'
print(word_count.description)   # 'Count the words in a piece of text.'
print(word_count.args)          # {'text': {'title': 'Text', 'type': 'string'}}

# tools are still callable; .invoke runs the underlying function
print(word_count.invoke({"text": "one two three"}))

