from langchain_core.tools import tool

@tool
def multiply(a: int, b: int) -> int:
    """Multiply two integers."""
    return a * b

@tool
def shout(text: str) -> str:
    """Uppercase the given text."""
    return text.upper()

TOOLS = {t.name: t for t in [multiply, shout]}

def run_tool_calls(tool_calls: list[dict]) -> list:
    results = []
    for call in tool_calls:
        tool_obj = TOOLS[call["name"]]        # look up by name
        results.append(tool_obj.invoke(call["args"]))  # run it
    return results

if __name__ == "__main__":
    # shape a real model would emit via bind_tools
    calls = [
        {"name": "multiply", "args": {"a": 6, "b": 7}},
        {"name": "shout", "args": {"text": "done"}},
    ]
    print(run_tool_calls(calls))
